"use client";

/**
 * Client loader + display metadata for the demonstration repository corpus
 * (public/demo/repository/corpus.json, generated by scripts/build-mock-corpus.ts).
 * Everything in the corpus is fictitious — see DemoNotice.
 */

import { useEffect, useState } from "react";
import type { RepositoryCorpus } from "./corpus-types";

/** Public-asset URL that respects the deployment basePath (empty on the dev server). */
export function assetUrl(p: string): string {
  const base = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
  return `${base}${p}`;
}

let cache: Promise<RepositoryCorpus> | null = null;
function loadCorpus(): Promise<RepositoryCorpus> {
  if (!cache) {
    cache = fetch(assetUrl("/demo/repository/corpus.json")).then((r) => {
      if (!r.ok) throw new Error(`Corpus could not be loaded (${r.status}).`);
      return r.json() as Promise<RepositoryCorpus>;
    });
  }
  return cache;
}

export function useCorpus(): { corpus?: RepositoryCorpus; error?: string } {
  const [state, setState] = useState<{ corpus?: RepositoryCorpus; error?: string }>({});
  useEffect(() => {
    let live = true;
    loadCorpus().then(
      (corpus) => live && setState({ corpus }),
      (err) => live && setState({ error: err instanceof Error ? err.message : String(err) })
    );
    return () => {
      live = false;
    };
  }, []);
  return state;
}

